	if ( take_off_enabled && this->m_indicator_data.m_was_in_air && on_ground ) {
		this->m_indicator_data.m_frames_in_air = 0;
		for ( auto& ind : g_velocity_indicators ) {
			if ( !ind.removing ) {
				ind.removing             = true;
				ind.targetOpacity        = 0.0f;
				ind.fade_delay           = 0.0f;
				ind.fade_delay_remaining = 0.0f;
				if ( !animate_velocity )
					ind.opacity = 0.0f;
			}
		}
		this->m_indicator_data.m_was_in_air = false;
		this->m_indicator_data.m_ground_time = 0.f;
	} else if ( !on_ground ) {
		this->m_indicator_data.m_frames_in_air++;
		if ( this->m_indicator_data.m_frames_in_air >= 2 )
			this->m_indicator_data.m_ground_time = 0.f;
	} else {
		this->m_indicator_data.m_frames_in_air = 0;
	}
	if ( !take_off_enabled ) {
		for ( auto& ind : g_velocity_indicators ) {
			if ( !ind.removing ) {
				ind.removing      = true;
				ind.targetOpacity = 0.0f;
				ind.fade_delay           = 0.0f;
				ind.fade_delay_remaining = ind.fade_delay;
				if ( !animate_velocity )
					ind.opacity = 0.0f;
			}
		}
	}
